import{_ as r,C as a,o as s,c as i,j as t,a as n,E as h,a2 as d}from"./chunks/framework.BxGh02fV.js";const w=JSON.parse('{"title":"Drift","description":"","frontmatter":{"title":"Drift"},"headers":[],"relativePath":"en/guide/drift.md","filePath":"en/guide/drift.md"}'),l={name:"en/guide/drift.md"};function c(f,e,g,u,p,m){const o=a("Capture");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"drift",tabindex:"-1"},[n("Drift "),t("a",{class:"header-anchor",href:"#drift","aria-label":'Permalink to "Drift"'},"​")],-1)),e[1]||(e[1]=t("p",null,'This screen checks that modified code matches declared work. You come here before a commit, or when an agent has touched the code, to see whether the rule "no code without a task in progress" is respected.',-1)),h(o,{name:"derive",alt:"The Drift screen: No drift verdict, active task Yes, list of modified code files"}),e[2]||(e[2]=d('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Under the <strong>Drift detector</strong> title, one card gathers:</p><ul><li>The <strong>verdict</strong>: <strong>No drift</strong> (green background) or <strong>Drift detected</strong> (orange background).</li><li><strong>Active task</strong>: <strong>Yes</strong> if at least one task of the project is <strong>In progress</strong>, whatever its story — this is the anti-drift hook&#39;s rule at commit time; <strong>No</strong> otherwise.</li><li><strong>Modified code files</strong>: the code files modified in the repository. If there are none, the screen shows &quot;No modified code file.&quot; Stacks that declare their own repository are checked too; their files are prefixed with the stack identifier.</li><li>Two buttons: <strong>Refresh</strong> and <strong>Install the pre-commit hook</strong>.</li></ul><h2 id="when-is-there-drift" tabindex="-1">When is there drift? <a class="header-anchor" href="#when-is-there-drift" aria-label="Permalink to &quot;When is there drift?&quot;">​</a></h2><p>There is drift when code files are modified <strong>and</strong> no task is <strong>In progress</strong>. Metadata files (<code>.effortless/</code>, <code>blueprints/</code>) do not count as code.</p><p>To clear a drift, set the relevant task to <strong>In progress</strong> on the <a href="/Effortless/en/guide/tasks.html">Tasks</a> screen, or create one.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Refresh</strong>: reads the repository state again. The screen also reloads by itself when the project changes.</li><li><strong>Install the pre-commit hook</strong>: installs a git hook that refuses code commits without a task in progress. The screen confirms with &quot;Success: Hook installed:&quot; followed by the hook path.</li><li>When the hook is already in place, the button becomes <strong>Reinstall the pre-commit hook</strong> and <strong>Refresh</strong> becomes the primary button.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Do not use <code>--no-verify</code> to get around the hook: declare the task instead.</li><li>If the screen shows an error, check that the folder is a git repository (<a href="/Effortless/en/guide/git.html">Git</a>).</li></ul><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>Agents have <code>effortless_drift_check</code> to read the same verdict and <code>effortless_drift_hook_install</code> to install the hook.</p>',12))])}const _=r(l,[["render",c]]);export{w as __pageData,_ as default};
